# Based on initial exploration, let's test the probe set K = {(1, 1), (3, 3), (3, 4)}
K = [(1, 1), (3, 3), (3, 4)]
num_probes = len(K)

signatures = {}
colliding_pairs = []

for i, P in enumerate(valid_sets):
    # Calculate the signature vector v(P, K)
    signature = []
    for k in K:
        # Check if the probe location k is in the configuration P
        is_black = 1 if k in P else 0
        signature.append(is_black)

    sig_tuple = tuple(signature)

    if sig_tuple in signatures:
        colliding_pairs.append((i, signatures[sig_tuple]))
    else:
        signatures[sig_tuple] = i

print(f"\nTesting probes K={K} (k={num_probes}):")
print(f"Number of unique signatures found: {len(signatures)}")
